import { motion } from "framer-motion";
import { Plus, Search, Truck } from "lucide-react";
import { Link, useNavigate, useSearchParams } from "react-router-dom";
import { Can } from "@/app/guards/Can";
import { EmptyState } from "@/components/feedback/EmptyState";
import { ErrorState } from "@/components/feedback/ErrorState";
import { PageContainer } from "@/components/layout/PageContainer";
import { PageHeader } from "@/components/layout/PageHeader";
import { DataTable, type DataTableColumn } from "@/components/tables/DataTable";
import { Pagination } from "@/components/tables/Pagination";
import { Button } from "@/components/ui/Button";
import { Input } from "@/components/ui/Input";
import { useVendorsPage } from "@/features/vendors/useVendors";
import { pageMotion } from "@/lib/motion";
import { readPageParams, writePageParams } from "@/lib/pagination";
import type { VendorOut } from "@/types/resources";

export function VendorsPage() { const navigate = useNavigate(); const [searchParams, setSearchParams] = useSearchParams(); const query = searchParams.get("q") ?? ""; const pagination = readPageParams(searchParams); const listQuery = useVendorsPage({ q: query || null, ...pagination }); const pageData = listQuery.data; const paginationProps = pageData ? { page: pageData.page, pageSize: pageData.page_size, total: pageData.total, totalPages: pageData.total_pages, onPageChange: (page: number) => setSearchParams(writePageParams(searchParams, { page })), onPageSizeChange: (page_size: typeof pageData.page_size) => setSearchParams(writePageParams(searchParams, { page_size })) } : undefined; function updateParams(next: Record<string, string | null>) { const resolved = new URLSearchParams(searchParams); Object.entries(next).forEach(([key, value]) => value ? resolved.set(key, value) : resolved.delete(key)); if (next.q !== undefined) resolved.delete("page"); setSearchParams(resolved); } const columns: Array<DataTableColumn<VendorOut>> = [{ id: "vendor", header: "المورد", cell: (row) => <div className="flex min-w-0 items-center gap-3"><span className="flex size-10 shrink-0 items-center justify-center rounded-xl bg-primary-soft text-primary"><Truck aria-hidden="true" className="size-4" /></span><div><p className="font-semibold text-foreground">{row.name}</p><p className="text-meta">{row.services_provided ?? "بدون خدمات محددة"}</p></div></div> }, { id: "phone", header: "الهاتف", cell: (row) => row.phone ?? "—" }, { id: "email", header: "البريد", cell: (row) => row.email ?? "—" }, { id: "notes", header: "ملاحظات", cell: (row) => row.notes ?? "—" }]; return <motion.div {...pageMotion}><PageContainer><PageHeader eyebrow="الموردون" title="الموردون" description="إدارة الموردين مع البحث المدعوم q." actions={<Can permission="vendors.create"><Button asChild className="rounded-full shadow-sm"><Link to="/vendors/new"><Plus aria-hidden="true" className="size-4" /> إضافة مورد</Link></Button></Can>} /><section className="grid gap-4 rounded-xl border border-border bg-card p-4 shadow-card md:grid-cols-[1fr_auto] md:items-end"><label className="block space-y-1.5"><span className="text-meta">بحث</span><span className="relative block"><Search aria-hidden="true" className="pointer-events-none absolute right-3.5 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" /><Input className="rounded-xl bg-muted/70 pr-11" defaultValue={query} placeholder="ابحث باسم المورد" onBlur={(event) => updateParams({ q: event.target.value.trim() || null })} onKeyDown={(event) => { if (event.key === "Enter") updateParams({ q: event.currentTarget.value.trim() || null }); }} /></span></label><Button className="h-11 rounded-xl" variant="outline" onClick={() => setSearchParams(new URLSearchParams())}>مسح البحث</Button></section>{listQuery.isError ? <ErrorState title="تعذر تحميل الموردين" description="تعذر تحميل قائمة الموردين." onRetry={() => void listQuery.refetch()} /> : <><div className="hidden md:block"><DataTable actions={(row) => <><Button asChild className="rounded-full" size="sm" variant="ghost"><Link to={`/vendors/${row.id}`}>عرض</Link></Button><Can permission="vendors.update"><Button asChild className="rounded-full" size="sm" variant="outline"><Link to={`/vendors/${row.id}/edit`}>تعديل</Link></Button></Can></>} columns={columns} data={pageData?.items ?? []} emptyAction={<Can permission="vendors.create"><Button asChild size="sm"><Link to="/vendors/new">إضافة مورد</Link></Button></Can>} emptyDescription="لا يوجد موردون مطابقون للبحث الحالي." emptyTitle="لا يوجد موردون" getRowId={(row) => row.id} loading={listQuery.isPending} pagination={paginationProps} updating={listQuery.isFetching && !listQuery.isPending} onRowClick={(row) => navigate(`/vendors/${row.id}`)} /></div><div className="grid gap-2 md:hidden">{listQuery.isPending ? <p className="rounded-lg border border-border bg-card px-4 py-5 text-sm text-muted-foreground">جاري تحميل الموردين...</p> : (pageData?.items ?? []).length === 0 ? <EmptyState compact action={<Can permission="vendors.create"><Button asChild size="sm"><Link to="/vendors/new">إضافة مورد</Link></Button></Can>} description="لا يوجد موردون مطابقون للبحث الحالي." title="لا يوجد موردون" /> : null}{(pageData?.items ?? []).map((vendor) => <Link key={vendor.id} className="rounded-xl border border-border bg-card p-4 shadow-card" to={`/vendors/${vendor.id}`}><p className="font-semibold text-foreground">{vendor.name}</p><p className="mt-1 text-meta">{vendor.phone ?? vendor.email ?? "بدون بيانات تواصل"}</p></Link>)}{paginationProps ? <Pagination {...paginationProps} isFetching={listQuery.isFetching && !listQuery.isPending} /> : null}</div></>}</PageContainer></motion.div>; }
